<?php $boards = is_array($boards ?? null) ? $boards : []; ?><div class="ui-page-index"><section class="page-header"><div><p class="eyebrow">Exams &amp; subjects</p><h1>Choose your examination</h1><p>Start every session with the right board context.</p></div></section><div class="ui-exam-grid exam-grid"><?php foreach ($boards as $board): ?><article class="card exam-card"><div class="exam-card-top"><span class="badge badge-info"><?= htmlspecialchars((string) ($board['code'] ?? 'Exam')) ?></span><span><?= count($board['subjects'] ?? []) ?> subjects</span></div><h2><?= htmlspecialchars((string) ($board['name'] ?? '')) ?></h2><p><?= htmlspecialchars((string) ($board['description'] ?? '')) ?></p><?php if (!empty($board['subjects'])): ?><div class="chip-list"><?php foreach ($board['subjects'] as $subject): ?><span class="chip"><?= htmlspecialchars((string) ($subject['name'] ?? '')) ?></span><?php endforeach; ?></div><?php endif; ?><a class="button" href="/quiz?exam=<?= urlencode((string) ($board['code'] ?? 'LET')) ?>">Configure practice</a></article><?php endforeach; ?></div></div>
